import * as z from "zod";

// Generated by expo-variant-env. Add a field here whenever you add a new
// EXPO_PUBLIC_* variable to .env.example.

const EnvSchema = z.object({
  EXPO_PUBLIC_API_BASE_URL: z.string(),
  EXPO_PUBLIC_API_KEY: z.string(),
  EXPO_PUBLIC_NETAPPSPAY_TEST_KEY: z.string(),
  EXPO_PUBLIC_NETAPPSPAY_KEY: z.string(),
});

const envVars = {
  EXPO_PUBLIC_API_BASE_URL: process.env.EXPO_PUBLIC_EXPO_PUBLIC_API_BASE_URL,
  EXPO_PUBLIC_API_KEY: process.env.EXPO_PUBLIC_EXPO_PUBLIC_API_KEY,
  EXPO_PUBLIC_NETAPPSPAY_TEST_KEY: process.env.EXPO_PUBLIC_EXPO_PUBLIC_NETAPPSPAY_TEST_KEY,
  EXPO_PUBLIC_NETAPPSPAY_KEY: process.env.EXPO_PUBLIC_EXPO_PUBLIC_NETAPPSPAY_KEY,
};

const parsed = EnvSchema.safeParse(envVars);

if (!parsed.success) {
  throw new Error(
    `Invalid env. Missing or invalid variables:\n${Object.entries(
      parsed.error.flatten().fieldErrors
    )
      .map(([key, errors]) => `- ${key}: ${errors}`)
      .join("\n")}`
  );
}

export const env = parsed.data;
